import json
from pathlib import Path
string={'type':'string'}
uid={'type':'string','pattern':'^[1-9][0-9]*$','description':'Numeric ID encoded as a string; never a JSON number.'}
ref=lambda name:{'$ref':'#/components/schemas/'+name}
command={'oneOf':[{'type':'object','additionalProperties':False,'required':['recipientUserId','type','text'],'properties':{'recipientUserId':uid,'type':{'const':'text'},'text':{'type':'string','minLength':1,'maxLength':1000}}},{'type':'object','additionalProperties':False,'required':['recipientUserId','type','stickerId'],'properties':{'recipientUserId':uid,'type':{'const':'sticker'},'stickerId':uid}}]}
operation={'type':'object','required':['operationId','command','state','createdAt','updatedAt'],'properties':{'operationId':{'type':'string','format':'uuid'},'command':ref('Command'),'state':{'enum':['queued','sending','verifying','succeeded','failed','uncertain']},'reason':string,'tiktokRejection':{'type':'object','description':'Numerical TikTok rejection diagnostics, when available. Older operations may omit this field.','required':['status','check'],'properties':{'status':{'type':'integer','minimum':0},'check':{'type':'integer','minimum':0},'businessCode':{'type':'integer','minimum':1,'description':'Detailed check_message.status_code when supplied by TikTok; absent in older rejections.'}}},'messageId':string,'createdAt':{'type':'string','format':'date-time'},'updatedAt':{'type':'string','format':'date-time'}}}
def response(code,description,schema):return {str(code):{'description':description,'content':{'application/json':{'schema':schema}}}}
paths={}
def endpoint(path,method,summary,schema,code=200):
    op={'summary':summary,'operationId':method+'_'+path.replace('/','_').replace('{','').replace('}',''),'responses':response(code,summary,schema)}
    if path.startswith('/v1'):op['responses'].update(response(401,'Invalid Bearer token',ref('Error')));op['responses'].update(response(503,'Dependency or storage unavailable',ref('Error')))
    if '{id}' in path:op['parameters']=[{'name':'id','in':'path','required':True,'schema':string}]
    paths.setdefault(path,{})[method]=op;return op
endpoint('/healthz','get','Process liveness',{'type':'object','properties':{'ok':{'type':'boolean'}}})['security']=[]
r=endpoint('/readyz','get','Session and baseline ready; sending may be paused',{'type':'object','properties':{'ready':{'type':'boolean'}}});r['security']=[];r['responses'].update(response(503,'Not ready',ref('Error')))
endpoint('/v1/status','get','Account, connection, operation counts, persistent pause and webhook failures',{'type':'object','properties':{'accountId':uid,'connected':{'type':'boolean'},'paused':{'type':'boolean'},'pauseReason':string,'queue':{'type':'object','additionalProperties':{'type':'integer'}},'lastPollAt':{'type':'string','format':'date-time'},'pollError':string,'webhook':{'type':'object','properties':{'pending':{'type':'integer'},'blocked':{'type':'integer'},'lastError':string}}}})
r=endpoint('/v1/messages','post','Accept command, not proof of delivery; duplicates return the original operation',ref('Operation'),202);r['parameters']=[{'name':'Idempotency-Key','in':'header','required':True,'schema':{'type':'string','minLength':1,'maxLength':256}}];r['requestBody']={'required':True,'content':{'application/json':{'schema':ref('Command')}}};r['responses'].update(response(400,'Invalid command or missing key',ref('Error')));r['responses'].update(response(409,'Same key with different command',ref('Error')));r['responses']['202']['headers']={'Location':{'schema':string,'description':'Operation URL'}}
r=endpoint('/v1/operations/{id}','get','Read operation',ref('Operation'));r['responses'].update(response(404,'Unknown operation',ref('Error')))
r=endpoint('/v1/operations/{id}/reconcile','post','Only read history; never send; no server ID means uncertain remains',ref('Operation'));r['responses'].update(response(404,'Unknown operation',ref('Error')));r['responses'].update(response(409,'Only uncertain operations can reconcile',ref('Error')))
sticker={'type':'object','required':['id','preview'],'properties':{'id':uid,'name':string,'preview':string}}
endpoint('/v1/stickers','get','Persistent local sticker catalogue; no chat lookup',{'type':'object','properties':{'stickers':{'type':'array','items':sticker}}})
r=endpoint('/v1/stickers/import','post','Copy an owned sticker from an existing conversation into the local catalogue',sticker)
r['requestBody']={'required':True,'content':{'application/json':{'schema':{'type':'object','additionalProperties':False,'required':['sourceUserId','messageId','name'],'properties':{'sourceUserId':uid,'messageId':uid,'name':{'type':'string','minLength':1,'maxLength':120}}}}}}
for code,description in [(400,'Invalid import'),(404,'Source conversation or sticker not found'),(409,'Catalogue ID already has different content'),(501,'Import unsupported by adapter')]:r['responses'].update(response(code,description,ref('Error')))
r=endpoint('/v1/stickers/{id}/preview','get','Read locally stored image without chat or CDN requests',{});r['responses']['200']['content']={mime:{'schema':{'type':'string','format':'binary'}} for mime in ['image/png','image/jpeg','image/gif','image/webp']};r['responses'].update(response(404,'Catalogue sticker not found',ref('Error')));r['responses'].update(response(400,'Invalid ID',ref('Error')))
endpoint('/v1/control/pause','post','Persist sending pause; active external send may finish',{'type':'object','properties':{'paused':{'const':True}}})
r=endpoint('/v1/control/resume','post','Validate session, baseline and absence of uncertain operations',{'type':'object','properties':{'paused':{'const':False}}});r['responses'].update(response(409,'Resume checks failed',ref('Error')))
event={'type':'object','required':['schemaVersion','eventId','type','accountId','occurredAt','detectedAt','data'],'properties':{'schemaVersion':{'const':'1'},'eventId':string,'type':{'const':'follower.created'},'accountId':uid,'occurredAt':{'type':'string','format':'date-time'},'detectedAt':{'type':'string','format':'date-time'},'data':{'type':'object','required':['userId'],'properties':{'userId':uid,'username':string}}}}
message={'type':'object','required':['messageId','senderId','direction','type','text','sentAt'],'properties':{'messageId':uid,'senderId':uid,'direction':{'enum':['incoming','outgoing']},'type':{'enum':['text','image','video','sticker','unknown']},'text':string,'sentAt':{'type':'string','format':'date-time'},'replyToMessageId':uid}}
history={'type':'object','required':['accountId','userId','conversationId','messages','nextCursor','exhausted','hasGaps'],'properties':{'accountId':uid,'userId':uid,'conversationId':string,'messages':{'type':'array','items':ref('HistoryMessage')},'nextCursor':string,'exhausted':{'type':'boolean','description':'Explicit empty server page. Proves only the end of currently visible history.'},'hasGaps':{'type':'boolean','description':'Hidden, recalled or unparseable rows were observed on this page.'}}}
r=endpoint('/v1/conversations/{userId}/messages','get','Read one page of existing direct-conversation history; no creation or mark-read',ref('MessagePage'))
r['parameters']=[{'name':'userId','in':'path','required':True,'schema':uid},{'name':'cursor','in':'query','required':False,'schema':uid}]
r['responses'].update(response(400,'Invalid user ID or cursor',ref('Error')));r['responses'].update(response(404,'Conversation not found in available inbox; not proof of no prior history',ref('Error')))
message_event=json.loads(json.dumps(event));message_event['properties']['type']={'const':'message.received'};message_event['properties']['data']={'type':'object','required':['userId','conversationId','messageId','message'],'properties':{'userId':uid,'conversationId':string,'messageId':uid,'message':ref('HistoryMessage')}}
doc={'openapi':'3.1.0','info':{'title':'TikTok Gateway','version':'0.3.3','description':'One account per service. Durable idempotency, conservative reconciliation, at-least-once webhooks. No exactly-once guarantee.'},'servers':[{'url':'http://localhost:8080'}],'security':[{'bearerAuth':[]}],'paths':paths,'components':{'securitySchemes':{'bearerAuth':{'type':'http','scheme':'bearer'}},'schemas':{'Command':command,'Operation':operation,'Error':{'type':'object','required':['error'],'properties':{'error':string}},'FollowerCreated':event}},'webhooks':{'follower.created':{'post':{'description':'Separate webhook Bearer token. Stable eventId across retries. 2xx acknowledges acceptance only.','requestBody':{'required':True,'content':{'application/json':{'schema':ref('FollowerCreated')}}},'responses':{'2XX':{'description':'Accepted; workflow may still be running'}}}}}}
doc['components']['schemas'].update({'HistoryMessage':message,'MessagePage':history,'MessageReceived':message_event})
doc['webhooks']['message.received']={'post':{'description':'Opt-in RECEIVE_MESSAGES=true. First poll establishes baseline. Stable event ID, incoming DMs only. Same webhook URL/token as followers; no business-state storage.','requestBody':{'required':True,'content':{'application/json':{'schema':ref('MessageReceived')}}},'responses':{'2XX':{'description':'Accepted; workflow may still be running'}}}}
doc['paths']['/v1/status']['get']['responses']['200']['content']['application/json']['schema']['properties']['incoming']={'type':'object','properties':{'startedAt':{'type':'string','format':'date-time'},'lastPollAt':{'type':'string','format':'date-time','description':'Latest completed inbox polling cycle, including partial success.'},'error':string,'failedConversations':{'type':'array','items':{'type':'object','required':['conversationId','userId','error','checkpointAt'],'properties':{'conversationId':string,'userId':uid,'error':string,'checkpointAt':{'type':'string','format':'date-time','description':'Preserved synchronization watermark; failed reads never advance it.'}}}}}}
Path('docs/openapi.json').write_text(json.dumps(doc,indent=2)+'\n')
